function frame(t){
  const dt=Math.min((t-last)/1000||0,.15);last=t;
  if(!document.hidden){
    const steering=input();
    if(g.mode!=='paused')clock+=dt;
    let stepped=false;
    if(g.mode==='playing'){hitStop=Math.max(0,hitStop-dt);C.advance(g,dt,steering);stepped=true;}
    if(stepped)events();crew.update(g.mode,dt);
    if(previousMode!==g.mode)syncMenu();previousMode=g.mode;
    if(g.mode==='playing'){
      shake*=Math.exp(-dt*16);
      if(!reduced&&Math.hypot(steering.x,steering.y)>.05){const a=g.heading+Math.PI;particles.push({x:g.player.x+Math.cos(a)*11,y:g.player.y+Math.sin(a)*11,vx:Math.cos(a)*45+(Math.random()-.5)*20,vy:Math.sin(a)*45+(Math.random()-.5)*20,life:.28,max:.35,color:g.weaponTime>0?weaponInfo[g.weaponKind].color:'#9af1d1',size:2});}
    }
    const wanted=g.mode==='playing'?Math.max(.45,Math.min(1,Math.hypot(steering.x,Math.min(0,steering.y)))):0;enginePower+=(wanted-enginePower)*(1-Math.exp(-dt*7));const turn=Math.atan2(Math.sin(g.heading-flightHeading),Math.cos(g.heading-flightHeading));flightHeading+=turn*(1-Math.exp(-dt*15));soundEngine.update(g.mode,g.enemies.some(e=>e.kind==='boss'));draw(dt);hudAccumulator+=dt;if(hudAccumulator>=1/24){hudAccumulator%=1/24;hud();}
  }
  requestAnimationFrame(frame);
}
